    pog.query(
      "TRUNCATE audit_log, acknowledgement_record, notification, inbound_email, document, ai_analysis, payment_terms_acceptance, payment, application_co_applicant, application_income_source, application, application_draft, vacancy_view, vacancy, landlord, storage_deletion_queue, processed_stripe_event, reference_call, reference_objection_log CASCADE",
    )
    |> pog.execute(db)
